import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import styled from 'styled-components';
import SpeechRecognizer from './SpeechRecognizer';
import StoryGenerator from './StoryGenerator';
import AudioPlayer from './AudioPlayer';
import { soundEffects } from '../services/mockApiService';

// Styled components
const StoryScreenContainer = styled.div`
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  padding: 20px;
  background-color: ${props => props.theme.colors.background};
`;

const Header = styled.header`
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 0;
`;

const Logo = styled.h1`
  font-size: 24px;
  color: ${props => props.theme.colors.primary};
  margin: 0;
`;

const NavButtons = styled.div`
  display: flex;
`;

const NavButton = styled.button`
  background-color: ${props => props.theme.colors.secondary};
  color: white;
  border: none;
  border-radius: 20px;
  padding: 8px 15px;
  margin-left: 10px;
  font-size: 14px;
  cursor: pointer;
  display: flex;
  align-items: center;

  svg {
    margin-right: 5px;
    width: 16px;
    height: 16px;
  }

  &:hover {
    background-color: ${props => props.theme.colors.primary};
  }
`;

const MainContent = styled.main`
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 20px 0;
`;

const AnimalCharacter = styled.div`
  width: 200px;
  height: 200px;
  margin-bottom: 20px;
  position: relative;

  img {
    width: 100%;
    height: 100%;
    object-fit: contain;
  }

  animation: ${props => props.isPlaying ? 'bounce 2s infinite ease-in-out' : 'none'};

  @keyframes bounce {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-15px); }
  }
`;

const SoundEffectIndicator = styled.div`
  position: absolute;
  top: -10px;
  right: -10px;
  background-color: ${props => props.theme.colors.accent};
  color: white;
  border-radius: 50%;
  width: 40px;
  height: 40px;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 20px;
  animation: pulse 1.5s infinite;

  @keyframes pulse {
    0% { transform: scale(1); opacity: 1; }
    50% { transform: scale(1.2); opacity: 0.8; }
    100% { transform: scale(1); opacity: 1; }
  }
`;

const StatusMessage = styled.div`
  margin: 20px 0;
  padding: 10px 20px;
  background-color: rgba(123, 104, 238, 0.1);
  border-radius: 10px;
  text-align: center;
  font-size: 16px;
  color: ${props => props.theme.colors.primary};
`;

// Main component
const StoryScreen = ({ currentStory, setCurrentStory, settings }) => {
  const navigate = useNavigate();
  const [isListening, setIsListening] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentSegmentIndex, setCurrentSegmentIndex] = useState(0);
  const [transcription, setTranscription] = useState('');
  const [keywords, setKeywords] = useState(null);
  const [statusMessage, setStatusMessage] = useState('Tap the microphone and say what story you want');
  const [activeSoundEffect, setActiveSoundEffect] = useState(null);

  // Handle speech recognition result
  const handleSpeechResult = (result) => {
    setTranscription(result.text);
    setKeywords(result.keywords);

    // If we don't have a story yet, generate one
    if (!currentStory) {
      setStatusMessage('Generating your story...');
    } else {
      setStatusMessage('Adapting your story...');
    }
  };

  // Handle story generation
  const handleStoryGenerated = (story) => {
    setCurrentStory(story);
    setStatusMessage(`Enjoy your story about ${story.animal_name} the ${story.primary_animal}!`);
  };

  // Handle story segment change
  const handleStorySegmentChange = (index) => {
    setCurrentSegmentIndex(index);
  };

  // Handle playback start
  const handlePlaybackStart = () => {
    setIsPlaying(true);

    // Randomly show a sound effect indicator
    if (currentStory && currentStory.sound_effects && currentStory.sound_effects.length > 0) {
      const randomEffect = currentStory.sound_effects[
        Math.floor(Math.random() * currentStory.sound_effects.length)
      ];
      setActiveSoundEffect(randomEffect);

      // Clear after a few seconds
      setTimeout(() => {
        setActiveSoundEffect(null);
      }, 3000);
    }
  };

  // Handle playback end
  const handlePlaybackEnd = () => {
    setIsPlaying(false);
    setActiveSoundEffect(null);
  };

  // Navigate to parent dashboard
  const goToParentDashboard = () => {
    navigate('/parent-dashboard');
  };

  // Navigate to bedtime mode
  const goToBedtimeMode = () => {
    navigate('/bedtime-mode');
  };

  // Get the current segment text for audio playback
  const getCurrentSegmentText = () => {
    if (!currentStory) return '';

    if (currentSegmentIndex === 0) {
      return currentStory.intro;
    } else if (currentSegmentIndex <= currentStory.middle_segments.length) {
      return currentStory.middle_segments[currentSegmentIndex - 1];
    } else {
      const endingIndex = currentSegmentIndex - currentStory.middle_segments.length - 1;
      return currentStory.endings[endingIndex];
    }
  };

  // Get background sounds for the current story
  const getBackgroundSounds = () => {
    if (!currentStory || !currentStory.sound_effects) return [];

    // Convert sound effect names to URLs
    return currentStory.sound_effects
      .filter(effect => soundEffects[effect])
      .map(effect => soundEffects[effect]);
  };

  // Get the animal image based on the current story
  const getAnimalImage = () => {
    if (!currentStory) return '/images/default_animal.png';

    const animalType = currentStory.primary_animal || 'default';

    switch (animalType) {
      case 'lion':
        return '/images/lion.png';
      case 'elephant':
        return '/images/elephant.png';
      case 'tiger':
        return '/images/tiger.png';
      default:
        return '/images/default_animal.png';
    }
  };

  return (
    <StoryScreenContainer>
      <Header>
        <Logo>AI StoryLand</Logo>
        <NavButtons>
          <NavButton onClick={goToBedtimeMode}>
            {/* Moon icon */}
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"></path>
            </svg>
            Bedtime
          </NavButton>
          <NavButton onClick={goToParentDashboard}>
            {/* User icon */}
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path>
              <circle cx="12" cy="7" r="4"></circle>
            </svg>
            Parent
          </NavButton>
        </NavButtons>
      </Header>

      <MainContent>
        {currentStory && (
          <AnimalCharacter isPlaying={isPlaying}>
            <img src={getAnimalImage()} alt={currentStory.primary_animal} />
            {activeSoundEffect && (
              <SoundEffectIndicator>🔊</SoundEffectIndicator>
            )}
          </AnimalCharacter>
        )}

        <StatusMessage>{statusMessage}</StatusMessage>

        <SpeechRecognizer 
          onSpeechResult={handleSpeechResult}
          initialPrompt="Tap the microphone and say what story you want"
        />

        {currentStory && (
          <>
            <StoryGenerator 
              initialKeywords={keywords}
              onStoryGenerated={handleStoryGenerated}
              onStorySegmentChange={handleStorySegmentChange}
              onError={(error) => setStatusMessage(`Error: ${error.message}`)}
            />

            <AudioPlayer 
              text={getCurrentSegmentText()}
              animalType={currentStory.primary_animal}
              effectIntensity={settings.voiceEffectIntensity}
              backgroundSounds={getBackgroundSounds()}
              onPlaybackStart={handlePlaybackStart}
              onPlaybackEnd={handlePlaybackEnd}
            />
          </>
        )}
      </MainContent>
    </StoryScreenContainer>
  );
};

export default StoryScreen;
